288	    public void setPot(String sheetId, BigDecimal pot) {
289	        jdbc.update("UPDATE sheet SET pot = ? WHERE id = ?", pot, sheetId);
290	    }
291	
292	    /** The sheet's alert threshold; null when blank (off). */
293	    public BigDecimal alertThreshold(String sheetId) {
294	        List<BigDecimal> found = jdbc.query("SELECT alert_threshold FROM sheet WHERE id = ?",
295	                (rs, i) -> rs.getBigDecimal("alert_threshold"), sheetId);
296	        return found.isEmpty() ? null : found.get(0);
297	    }
