314	    /** The sheet's parent sheet id; null when blank (none). Not dated: read from the sheet as it is now, also on a
315	     *  screen showing the sheet as of a date. */
316	    public String parent(String sheetId) {
317	        List<String> found = jdbc.query("SELECT parent_id FROM PUBLIC.sheet WHERE id = ?",
318	                (rs, i) -> rs.getString("parent_id"), sheetId);
319	        return found.isEmpty() ? null : found.get(0);
320	    }
321	
322	    public void setParent(String sheetId, String parent) {
