326	    /** A sheet's ancestors, nearest first: its parent, the parent's parent and so on, stopping at a sheet seen
327	     *  before. */
328	    public List<String> lineage(String sheetId) {
329	        List<String> found = new java.util.ArrayList<>();
330	        for (String at = parent(sheetId); at != null && !found.contains(at) && !at.equals(sheetId); at = parent(at)) {
331	            found.add(at);
332	        }
333	        return found;
334	    }
335	
336	    /** A sheet's descendants: the sheets naming it as their parent, their children and so on, nearer first,
337	     *  each once and never the sheet itself. */
338	    public List<String> descendants(String sheetId) {
339	        List<String> found = new java.util.ArrayList<>();
340	        java.util.Deque<String> pending = new java.util.ArrayDeque<>(List.of(sheetId));
341	        while (!pending.isEmpty()) {
342	            for (String child : jdbc.queryForList("SELECT id FROM sheet WHERE parent_id = ? ORDER BY id", String.class, pending.poll())) {
343	                if (child.equals(sheetId) || found.contains(child)) continue;
344	                found.add(child);
345	                pending.add(child);
346	            }
347	        }
348	        return found;
349	    }
