357	    /** The sheet's grace days; null when blank (off). */
358	    public Integer graceDays(String sheetId) {
359	        List<Integer> found = jdbc.query("SELECT grace_days FROM sheet WHERE id = ?",
360	                (rs, i) -> (Integer) rs.getObject("grace_days", Integer.class), sheetId);
361	        return found.isEmpty() ? null : found.get(0);
362	    }
363	
364	    public void setGraceDays(String sheetId, Integer days) {
