368	    /** The role a user name acts in on the sheet: steward while a delegation to them covers the sheet's today,
369	     *  else their own role. */
370	    public String role(String sheetId, String user) {
371	        return delegator(sheetId, user) != null ? STEWARD : ownRole(sheetId, user);
372	    }
