387	     *  null when none does. */
388	    public String delegator(String sheetId, String user) {
389	        List<String> found = jdbc.query("SELECT by_user FROM delegation WHERE sheet_id = ? AND user_name = ?"
390	                + " AND from_date <= ? AND to_date >= ? ORDER BY id DESC LIMIT 1",
391	                (rs, i) -> rs.getString("by_user"), sheetId, user, Date.valueOf(today(sheetId)), Date.valueOf(today(sheetId)));
392	        return found.isEmpty() ? null : found.get(0);
393	    }
