400	    /** The sheet's holidays (yyyy-MM-dd), earliest first. */
401	    public List<String> holidays(String sheetId) {
402	        return jdbc.query("SELECT holiday_date FROM holiday WHERE sheet_id = ? ORDER BY holiday_date",
403	                (rs, i) -> rs.getDate("holiday_date").toLocalDate().toString(), sheetId);
404	    }
405	
406	    public void addHoliday(String sheetId, LocalDate date) {
407	        jdbc.update("INSERT INTO holiday (sheet_id, holiday_date) VALUES (?, ?)", sheetId, Date.valueOf(date));
408	    }
409	
410	    /** The sheet's void reasons, in the order they were added. */
411	    public List<String> voidReasons(String sheetId) {
