418	                + " VALUES (?, (SELECT COALESCE(MAX(position), 0) + 1 FROM void_reason WHERE sheet_id = ?), ?)",
419	                sheetId, sheetId, reason);
420	    }
421	
422	    /** The terms-th business day after a date on the sheet: counting forward from the day after it, skipping
423	     *  every Saturday, Sunday and holiday on the sheet; the date itself for terms 0. */
424	    public LocalDate businessDaysAfter(String sheetId, LocalDate date, int terms) {
425	        return businessDaysAfter(new java.util.HashSet<>(holidays(sheetId)), date, terms);
426	    }
427	
428	    /** The terms-th business day after a date, skipping every Saturday, Sunday and one of the holidays (yyyy-MM-dd). */
429	    public static LocalDate businessDaysAfter(java.util.Set<String> holidays, LocalDate date, int terms) {
430	        int counted = 0;
431	        while (counted < terms) {
432	            date = date.plusDays(1);
433	            java.time.DayOfWeek day = date.getDayOfWeek();
434	            if (day != java.time.DayOfWeek.SATURDAY && day != java.time.DayOfWeek.SUNDAY
435	                    && !holidays.contains(date.toString())) {
436	                counted++;
437	            }
438	        }
439	        return date;
440	    }
