443	    public List<Delegation> delegations(String sheetId) {
444	        return jdbc.query("SELECT user_name, by_user, from_date, to_date FROM delegation WHERE sheet_id = ? ORDER BY id",
445	                (rs, i) -> new Delegation(rs.getString("user_name"), rs.getString("by_user"),
446	                        rs.getDate("from_date").toLocalDate().toString(), rs.getDate("to_date").toLocalDate().toString()),
447	                sheetId);
448	    }
