450	    /** The permission matrix entries set on the sheet, by action, each a comma separated list of roles; an
451	     *  action not listed keeps the standing rule. */
452	    public Map<String, String> permissions(String sheetId) {
453	        Map<String, String> perms = new LinkedHashMap<>();
454	        jdbc.query("SELECT action, roles FROM sheet_permission WHERE sheet_id = ?",
455	                (org.springframework.jdbc.core.RowCallbackHandler) rs -> perms.put(rs.getString("action"), rs.getString("roles")),
456	                sheetId);
457	        Map<String, String> ordered = new LinkedHashMap<>();
458	        for (String action : PERMISSION_ACTIONS) {
459	            if (perms.containsKey(action)) ordered.put(action, perms.get(action));
460	        }
461	        return ordered;
462	    }
463	
464	    /** Set the roles that may take an action (a comma separated list); null or blank restores the standing rule. */
465	    public void setPermission(String sheetId, String action, String roles) {
466	        if (roles == null || roles.isEmpty()) {
467	            jdbc.update("DELETE FROM sheet_permission WHERE sheet_id = ? AND action = ?", sheetId, action);
468	        } else {
469	            jdbc.update("MERGE INTO sheet_permission (sheet_id, action, roles) KEY (sheet_id, action) VALUES (?, ?, ?)",
470	                    sheetId, action, roles);
471	        }
472	    }
473	
474	    /** Whether a user may take an action on the sheet: by the sheet's permission matrix entry for it, else the
475	     *  standing rule (open, settle, void and close by clerk and steward; reassign and reopen by steward). */
476	    public boolean allows(String sheetId, String action, String user) {
477	        List<String> found = jdbc.query("SELECT roles FROM sheet_permission WHERE sheet_id = ? AND action = ?",
478	                (rs, i) -> rs.getString("roles"), sheetId, action);
479	        List<String> roles = found.isEmpty()
480	                ? (action.equals("reassign") || action.equals("reopen") ? List.of(STEWARD) : List.of(CLERK, STEWARD))
481	                : List.of(found.get(0).split(","));
482	        return roles.contains(role(sheetId, user));
483	    }
484	
485	    /** A limit as shown: two decimals, a dot, no grouping. */
486	    public static String money(BigDecimal v) {
487	        return v.setScale(2).toPlainString();
488	    }
489	}
